public class Order : Entity<OrderId>, IAggregateRoot
{
    private readonly List<OrderLine> _lines = new();

    // Factories ensure valid initial state
    public static Order Create(OrderId id, CustomerId customer, ShippingAddress address)
    {
        var order = new Order(id)
        {
            _customer = customer,
            _status = OrderStatus.Pending,
            _shippingAddress = address,
            _createdAt = DateTime.UtcNow
        };
        order.AddDomainEvent(new OrderCreatedEvent(order.Id));
        return order;
    }

    // Behavior method, not a setter
    public void AddItem(ProductId productId, Money price, int quantity)
    {
        if (_status != OrderStatus.Pending)
            throw new InvalidOperationException(
                $"Cannot add items to order in { _status} state");

        var line = new OrderLine(productId, price, quantity);
        _lines.Add(line);
        AddDomainEvent(new OrderItemAddedEvent(Id, line.Id));
    }

    public void Confirm()
    {
        if (!_lines.Any())
            throw new InvalidOperationException("Cannot confirm an empty order");
        _status = OrderStatus.Confirmed;
        AddDomainEvent(new OrderConfirmedEvent(Id));
    }
}

public sealed class Money : ValueObject
{
    public decimal Amount { get; }
    public string Currency { get; }

    public Money(decimal amount, string currency)
    {
        if (amount < 0) throw new ArgumentException("Amount cannot be negative", nameof(amount));
        if (string.IsNullOrWhiteSpace(currency)) throw new ArgumentException("Currency is required", nameof(currency));
        Amount = amount;
        Currency = currency;
    }

    public static Money operator +(Money left, Money right) =>
        left.Currency == right.Currency
            ? new(left.Amount + right.Amount, left.Currency)
            : throw new InvalidOperationException("Cannot add different currencies");

    protected override IEnumerable<object> GetEqualityComponents()
    {
        yield return Amount;
        yield return Currency;
    }
}

// Domain layer defines the contract
public interface IOrderRepository
{
    Task<Order?> GetByIdAsync(OrderId id, CancellationToken ct = default);
    Task<IReadOnlyList<Order>> ListAsync(ISpecification<Order> spec, CancellationToken ct = default);
    Task<int> CountAsync(ISpecification<Order> spec, CancellationToken ct = default);
    void Add(Order order);
    void Update(Order order);
    void Delete(Order order);
}

// Infrastructure layer implements it
public class EfOrderRepository : IOrderRepository
{
    private readonly AppDbContext _context;
    public EfOrderRepository(AppDbContext context) => _context = context;

    public async Task<Order?> GetByIdAsync(OrderId id, CancellationToken ct = default)
        => await _context.Orders.FindAsync([id], ct);

    public async Task<IReadOnlyList<Order>> ListAsync(
        ISpecification<Order> spec, CancellationToken ct = default)
        => await _context.Orders.WithSpecification(spec).ToListAsync(ct);

    public void Add(Order order) => _context.Orders.Add(order);
    public void Update(Order order) => _context.Entry(order).State = EntityState.Modified;
    public void Delete(Order order) => _context.Orders.Remove(order);
}

// Base entity with event collection
public abstract class Entity<TId> : IEquatable<Entity<TId>>
{
    private readonly List<IDomainEvent> _domainEvents = new();
    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    public void AddDomainEvent(IDomainEvent event)
        => _domainEvents.Add(event);

    public void ClearDomainEvents() => _domainEvents.Clear();
}

// Publish events in DbContext SaveChanges
public override async Task<int> SaveChangesAsync(CancellationToken ct = default)
{
    var domainEvents = ChangeTracker.Entries<Entity>()
        .Where(e => e.DomainEvents.Any())
        .SelectMany(e => e.DomainEvents)
        .ToList();

    foreach (var domainEvent in domainEvents)
        await _mediator.Publish(domainEvent, ct);

    return await base.SaveChangesAsync(ct);
}
